import React from 'react';
import { ArrowUpRight } from 'lucide-react';
import { Link } from 'react-router-dom';
import { portfolioData } from '../../data/portfolioData';
import { useLanguage } from '../../context/LanguageContext';
import { PageWrapper } from '../../shared/components/PageWrapper';

const Skills = () => {
  const { language } = useLanguage();
  const copy = {
    fr: {
      eyebrow: 'Compétences',
      title: 'Les outils avec lesquels je construis.',
      intro: 'Technologies et pratiques travaillées pendant ma formation et mes projets.',
      next: 'Voir les projets',
      groups: {
        Core: 'Fondamentaux',
        Frameworks: 'Frameworks',
        Styling: 'Style & design',
        Languages: 'Langages',
        SQL: 'Bases relationnelles',
        NoSQL: 'Bases NoSQL',
        Editors: 'Éditeurs',
        VCS: 'Gestion de versions',
        Design: 'Design',
        Testing: 'Tests',
        API: 'API',
        Methods: 'Méthodes'
      }
    },
    en: {
      eyebrow: 'Skills',
      title: 'Tools I use to build.',
      intro: 'Technologies and practices explored through my studies and projects.',
      next: 'Explore projects',
      groups: {
        Core: 'Fundamentals',
        Frameworks: 'Frameworks',
        Styling: 'Styling & design',
        Languages: 'Languages',
        SQL: 'Relational databases',
        NoSQL: 'NoSQL databases',
        Editors: 'Editors',
        VCS: 'Version control',
        Design: 'Design',
        Testing: 'Testing',
        API: 'APIs',
        Methods: 'Methods'
      }
    },
    ar: {
      eyebrow: 'المهارات',
      title: 'أدوات أستخدمها في التطوير.',
      intro: 'تقنيات وممارسات اكتسبتها من خلال التكوين والمشاريع.',
      next: 'اكتشف المشاريع',
      groups: {
        Core: 'الأساسيات',
        Frameworks: 'أطر العمل',
        Styling: 'التنسيق والتصميم',
        Languages: 'اللغات',
        SQL: 'قواعد البيانات العلائقية',
        NoSQL: 'قواعد بيانات NoSQL',
        Editors: 'المحررات',
        VCS: 'إدارة الإصدارات',
        Design: 'التصميم',
        Testing: 'الاختبار',
        API: 'واجهات API',
        Methods: 'المنهجيات'
      }
    },
    es: {
      eyebrow: 'Habilidades',
      title: 'Herramientas con las que construyo.',
      intro: 'Tecnologías y prácticas exploradas durante mis estudios y proyectos.',
      next: 'Ver proyectos',
      groups: {
        Core: 'Fundamentos',
        Frameworks: 'Frameworks',
        Styling: 'Estilos y diseño',
        Languages: 'Lenguajes',
        SQL: 'Bases relacionales',
        NoSQL: 'Bases NoSQL',
        Editors: 'Editores',
        VCS: 'Control de versiones',
        Design: 'Diseño',
        Testing: 'Pruebas',
        API: 'APIs',
        Methods: 'Métodos'
      }
    }
  }[language];
  const categoryLabels = {
    Frontend: portfolioData.common[language].catFrontend,
    Backend: portfolioData.common[language].catBackend,
    Database: portfolioData.common[language].catDatabase,
    Tools: portfolioData.common[language].catTools,
    Other: portfolioData.common[language].catOther
  };

  return (
    <PageWrapper>
      <header className="max-w-3xl">
        <p className="eyebrow">{copy.eyebrow}</p>
        <h1 className="display-heading mt-3 text-4xl leading-tight sm:text-5xl">{copy.title}</h1>
        <p className="mt-4 max-w-2xl text-base leading-7 text-[var(--muted)]">{copy.intro}</p>
      </header>

      <div className="mt-12 grid gap-4 md:grid-cols-2">
        {portfolioData.skills.map((skill, index) => (
          <article key={skill.name} className="surface-card p-6 sm:p-8">
            <div className="flex items-start gap-4">
              <span className="eyebrow pt-1">0{index + 1}</span>
              <div className="min-w-0 flex-1">
                <h2 className="text-xl font-semibold">{categoryLabels[skill.name] || skill.name}</h2>
                <div className="mt-5 space-y-5">
                  {skill.groups.map((group) => (
                    <div key={group.name}>
                      <h3 className="text-xs font-semibold uppercase tracking-[0.1em] text-[var(--muted)]">
                        {copy.groups[group.name] || group.name}
                      </h3>
                      <ul className="mt-2 flex flex-wrap gap-2">
                        {group.items.map((item) => (
                          <li key={item} className="rounded-full bg-[var(--accent-soft)] px-3 py-1.5 text-sm text-[var(--ink)]">
                            {item}
                          </li>
                        ))}
                      </ul>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </article>
        ))}
      </div>

      <Link to="/projects" className="mt-10 inline-flex items-center gap-2 text-sm font-semibold text-[var(--accent)] hover:underline">
        {copy.next}
        <ArrowUpRight size={16} />
      </Link>
    </PageWrapper>
  );
};

export default Skills;
